// Changes: moved from parser.c, frees only text the lexer marks with value_type
// TEXT (ADR-0002).
/**
 * @brief Frees the text owned by a token (if any)
 */
static void token_free(Token* token) {
  if (token->value_type == TEXT) {
    free(token->value.text);
    token->value.text = NULL;
  }
}

// Changes: moved from parser.c, reads the put-back token first.
/**
 * @brief Reads the next token from the source, or the one put back
 */
static Token source_read(Ctx* ctx, TokenLayer* layer) {
  if (layer->has_put_back) {
    layer->has_put_back = false;
    return layer->put_back;
  }
  return layer->next(ctx, layer->source);
}

// Changes: moved from parser.c, puts a token back for source_read.
/**
 * @brief Puts a token back, source_read returns it next
 */
static void source_put_back(TokenLayer* layer, Token token) {
  layer->put_back = token;
  layer->has_put_back = true;
}

// Changes: moved from parser.c, counts the open parentheses, interpolated
// strings and ${.
/**
 * @brief Counts the constructs a source token opens or closes
 *
 * A closing token never takes a count below 0, a stray one is a syntax error
 * the grammar reports.
 */
static void track_nesting(TokenLayer* layer, TokenType type) {
  size_t* depth;
  bool opens;
  switch (type) {
    case L_PAREN:
    case R_PAREN:
      depth = &layer->paren_depth;
      opens = type == L_PAREN;
      break;
    case S_STRING_START:
    case TRIPLE_S_STRING_START:
    case S_STRING_END:
    case TRIPLE_S_STRING_END:
      depth = &layer->string_depth;
      opens = type == S_STRING_START || type == TRIPLE_S_STRING_START;
      break;
    case DOLLAR_EXPRESSION_START:
    case DOLLAR_EXPRESSION_END:
      depth = &layer->dollar_depth;
      opens = type == DOLLAR_EXPRESSION_START;
      break;
    default:
      return;
  }
  if (opens)
    (*depth)++;
  else if (*depth > 0)
    (*depth)--;
}

// Changes: moved from parser.c, adapts the lexer's stream (ADR-0007): reads
// through the put-back slot, maps `()` to TYPE_UNIT, hides line breaks inside
// parentheses, skips blank and comment-only lines, ends a last line without a
// line break, treats a line without a raw indent as column 0 (closes every
// block) and holds back the token that closed blocks.
/**
 * @brief Reads the next token the grammar should see from the token source
 */
static Token fetch_token(Ctx* ctx, TokenLayer* layer) {
  layer->fetched_after_break = false;

  // Deliver block closes left over from a drop by more than one level
  if (layer->pending_closes > 0) {
    layer->pending_closes--;
    return layer->pending_close;
  }

  if (layer->has_held) {
    layer->has_held = false;
    return layer->held;
  }

  while (true) {
    Token token = source_read(ctx, layer);

    // The lexer's `()` is the grammar's TYPE_UNIT
    if (token.type == UNIT)
      token.type = TYPE_UNIT;

    track_nesting(layer, token.type);
    // Line breaks inside parentheses are hidden, except in string text
    bool in_string_text = layer->string_depth > layer->dollar_depth;
    if (layer->paren_depth > 0 && !in_string_text &&
        (token.type == EOL_TOKEN || token.type == INDENT)) {
      layer->fetched_after_break = true;
      continue;
    }

    // An EOL_TOKEN starting a line ends a blank or comment-only line
    if (token.type == EOL_TOKEN && layer->at_line_start)
      continue;

    // A raw indent followed by the end of its line or of the file starts a
    // blank or comment-only line and decides nothing
    if (token.type == INDENT) {
      Token after = source_read(ctx, layer);
      if (after.type == EOF_TOKEN)
        source_put_back(layer, after);
      if (after.type == EOL_TOKEN || after.type == EOF_TOKEN)
        continue;
      source_put_back(layer, after);
    }

    // The end of file ends a last line written without a line break
    if (token.type == EOF_TOKEN && !layer->at_line_start) {
      source_put_back(layer, token);
      layer->at_line_start = true;
      return (Token){
          .type = EOL_TOKEN, .line = token.line, .column = token.column};
    }

    // A line without a raw indent is in column 0 and the end of file ends the
    // last line: both close every open block, as a raw indent of 0 would.
    bool starts_line = layer->at_line_start;
    layer->at_line_start = token.type == EOL_TOKEN || token.type == EOF_TOKEN;
    bool closes_all = (token.type == EOF_TOKEN || starts_line) &&
                      token.type != INDENT && token.type != EOL_TOKEN &&
                      layer->indents.count > 1;
    if (token.type != INDENT && !closes_all)
      return token;

    IndentStack* indents = &layer->indents;
    int indentation = closes_all ? 0 : token.value.integer;
    int enclosing = indents->data[indents->count - 1];

    // Same block, the raw indent is not visible to the grammar
    if (indentation == enclosing)
      continue;

    // Deeper, block open
    if (indentation > enclosing) {
      array_append(ctx, indents, indentation);
      return token;
    }

    // Shallower, one block close per closed level
    size_t closes = 0;
    while (indents->data[indents->count - 1] > indentation) {
      indents->count--;
      closes++;
    }
    if (indents->data[indents->count - 1] != indentation)
      THROW(
          E_SYNTAX_ERROR,
          "%zu:%zu: syntax error: indentation of %d matches no enclosing block",
          token.line, token.column, indentation);

    // A raw indent is spent, any other token comes after the closes
    if (token.type != INDENT) {
      layer->held = token;
      layer->has_held = true;
    }
    Token close = {.type = INDENT, .line = token.line, .column = token.column};
    layer->pending_closes = closes - 1;
    layer->pending_close = close;
    return close;
  }
}

// Changes: new, the lexer as a token source (was lexer_source_next in
// parser.c); the contract describes the stream the lexer emits, which
// fetch_token adapts.
Token token_layer_lexer_next(Ctx* ctx, void* source) {
  (void)source;
  return next_token(ctx);
}

// Changes: new, the layer's initial state (was in parser_init); no token is
// held back and the first token starts a line.
void token_layer_init(Ctx* ctx,
                      TokenLayer* layer,
                      TokenSourceNext next,
                      void* source) {
  *layer = (TokenLayer){
      .next = next,
      .source = source,
      .current = {.type = EOF_TOKEN},
      .has_peeked = false,
      .indents = ARRAY_EMPTY,
      .pending_closes = 0,
      .at_line_start = true,
      .has_held = false,
  };

  // Top level, the bottom of the indentation stack
  array_append(ctx, &layer->indents, 0);

  token_layer_advance(ctx, layer);
}

// Changes: new, frees the tokens and the indentation stack (was in
// parser_cleanup), also the held-back and put-back tokens.
void token_layer_free(TokenLayer* layer) {
  token_free(&layer->current);
  if (layer->has_peeked)
    token_free(&layer->peeked);
  if (layer->has_held)
    token_free(&layer->held);
  if (layer->has_put_back)
    token_free(&layer->put_back);
  array_free(&layer->indents);
}

// Changes: new, the delivered current token.
const Token* token_layer_current(const TokenLayer* layer) {
  return &layer->current;
}

// Changes: moved from parser.c (was parser_advance), the hidden line break
// comes with the token.
void token_layer_advance(Ctx* ctx, TokenLayer* layer) {
  token_free(&layer->current);

  // A peeked token was already fetched (and translated), it comes next
  if (layer->has_peeked) {
    layer->current = layer->peeked;
    layer->current_after_break = layer->peeked_after_break;
    layer->has_peeked = false;
    return;
  }

  layer->current = fetch_token(ctx, layer);
  layer->current_after_break = layer->fetched_after_break;
}

// Changes: moved from parser.c (was parser_peek), fetches the token after the
// current one through the layer and keeps it until token_layer_advance moves to
// it.
const Token* token_layer_peek(Ctx* ctx, TokenLayer* layer) {
  if (!layer->has_peeked) {
    layer->peeked = fetch_token(ctx, layer);
    layer->peeked_after_break = layer->fetched_after_break;
    layer->has_peeked = true;
  }
  return &layer->peeked;
}

// Changes: new, whether a hidden line break came before the current token.
bool token_layer_after_line_break(const TokenLayer* layer) {
  return layer->current_after_break;
}
